package com.phrasecards.app;
import android.app.*;import android.content.*;import android.os.Build;import org.json.*;import java.io.*;import java.util.*;
public class NotificationReceiver extends BroadcastReceiver{
 static final String PREF="zope_flashcards_v81",CH="hard_cards";
 public void onReceive(Context c,Intent ignored){try{android.content.SharedPreferences sp=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);ArrayList<String> ids=new ArrayList<>();for(Map.Entry<String,?> e:sp.getAll().entrySet())if(e.getKey().endsWith("_result")&&e.getValue() instanceof Integer&&((Integer)e.getValue())==-1)ids.add(e.getKey().substring(0,e.getKey().length()-7));if(ids.isEmpty())return;String id=ids.get(new Random().nextInt(ids.size()));String[] card=find(c,sp,id);if(card==null)return;NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(Build.VERSION.SDK_INT>=26)nm.createNotificationChannel(new NotificationChannel(CH,"Hard card reminders",NotificationManager.IMPORTANCE_DEFAULT));Intent open=new Intent(c,MainActivity.class).putExtra("open_card_id",id).setFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent pi=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b;if(Build.VERSION.SDK_INT>=26)b=new Notification.Builder(c,CH);else b=new Notification.Builder(c);b.setSmallIcon(R.mipmap.ic_launcher).setContentTitle("Zope Flash Cards • Hard card").setContentText(card[2]).setStyle(new Notification.BigTextStyle().bigText(card[2])).setContentIntent(pi).setAutoCancel(true);nm.notify((int)(System.currentTimeMillis()%100000),b.build());}catch(Exception ignored){}}
 static String[] find(Context c,android.content.SharedPreferences sp,String id)throws Exception{JSONArray custom=new JSONArray(sp.getString("customCards","[]"));for(int i=0;i<custom.length();i++){JSONObject o=custom.getJSONObject(i);if(id.equals(o.optString("id")))return new String[]{id,o.optString("lang"),o.optString("p")};}InputStream in=c.getAssets().open("seed_cards.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[]buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);in.close();JSONArray seed=new JSONArray(out.toString("UTF-8"));for(int i=0;i<seed.length();i++){JSONObject o=seed.getJSONObject(i);if(id.equals(o.optString("id")))return new String[]{id,o.optString("lang"),o.optString("phrase")};}return null;}
}
